{ "jsonrpc": "2.0", "id": 42, "method": "resources/read", "params": { "uri": "file:///notes.md" } }

// its response, later, matched purely by id
{ "jsonrpc": "2.0", "id": 42, "result": { "contents": [ { "uri": "file:///notes.md", "text": "meeting notes" } ] } }

pending = {}

def send_request(method, params):
    request_id = next_id()
    pending[request_id] = create_future()
    transport.send({"jsonrpc": "2.0", "id": request_id, "method": method, "params": params})
    return pending[request_id]

def on_message(message):
    if "id" in message and ("result" in message or "error" in message):
        future = pending.pop(message["id"], None)
        if future:
            if "result" in message:
                future.resolve(message["result"])
            else:
                future.reject(message["error"])

function handleIncoming(message, pending) {
  if (!("id" in message)) {
    return; // notification, not a response, handle elsewhere
  }
  const entry = pending.get(message.id);
  if (!entry) {
    return; // unknown id, nothing waiting on it
  }
  pending.delete(message.id);
  if ("result" in message) {
    entry.resolve(message.result);
  } else if ("error" in message) {
    entry.reject(message.error);
  }
}
